function tablePage(){if(state.route==='section')return sectionsPage();const s=SCHEMAS[state.route],list=filtered(),allCols=state.subtab==='Payments'&&state.route==='hope-subscription'?[['id','ID'],['hospital','Hospital'],['plan','Plan'],['amount','Amount'],['payments','Type'],['status','Status'],['created','Started']]:s.cols,cols=allCols.filter(([k])=>!(state.hidden[state.route]||[]).includes(k)),start=(state.page-1)*state.size;let pages=Math.max(1,Math.ceil(list.length/state.size));if(state.page>pages){state.page=pages;return tablePage();}let pageRows=list.slice(start,start+state.size);
 const summary=['hope-order','hope-subscription','hope-user'].includes(state.route)?`<div class="headerstats">${(state.route==='hope-order'?['All Orders','Pending','Confirmed','Paid','Unpaid','Delivered']:state.route==='hope-subscription'?['Total Subscriptions','Active','Expired']:['Total Users','Active','Inactive']).map((label,i)=>`<button data-action="summaryfilter" data-value="${i?label:''}"><span>${label}</span><b>${i?rows().filter(r=>r.status===label||r.payment===label||r.deliveryStatus===label).length:rows().length}</b></button>`).join('')}</div>`:'';
 return`<div class="crumb"><a href="${link('dashboard')}">Dashboard</a> / ${s.title}</div>${s.meeting?filters(s.fixedType):''}${summary}<section class="panel tablepanel">${extraFilters()}<div class="toolbar"><h2>${s.title}</h2>${s.meeting?`<button data-action="view" data-value="table" title="Table view" aria-label="Table view">${icon('list')}</button><button data-action="view" data-value="cards" aria-label="Card view" title="Card view">${icon('box')}</button>`:''}<button data-action="columns">Columns</button><input id="table-search" aria-label="Search records" placeholder="${s.meeting?'Search meetings...':'Search...'}" value="${esc(state.search)}"><button data-action="export">${icon('download')}Export Excel</button>${s.noAdd?'<button data-action="refresh">Refresh</button>':`<button class="primary" data-action="add">${icon('plus')}Add ${s.singular}</button>`}</div><div class="notice">Sample records · Changes save in this browser only.</div>${state.view==='cards'&&s.meeting?`<div class="cards">${pageRows.map(r=>`<article class="panel meetingcard"><h3><a href="${link('sales-meeting',r.id)}">${esc(r.name)}</a></h3>${badge(r.meetingStatus)}<p class="muted">${r.type} · ${esc(r.location)}</p><p>${esc(r.employee)}</p><small>${date(r.created)}</small><div class="actions"><button data-action="edit" data-id="${r.id}">Edit</button><a class="btn" href="${link('sales-meeting',r.id)}">View</a></div></article>`).join('')}</div>`:`<div class="tablewrap"><table><thead><tr>${cols.map(([k,label])=>`<th scope="col" aria-sort="${state.sort===k?(state.desc?'descending':'ascending'):'none'}"><button data-action="sort" data-value="${k}">${label} ${state.sort===k?(state.desc?'↓':'↑'):''}</button></th>`).join('')}<th scope="col">Action</th></tr></thead><tbody>${pageRows.map(r=>`<tr>${cols.map(([k])=>`<td>${cell(r,k)}</td>`).join('')}<td><div class="rowbuttons">${s.meeting?`<a class="btn" href="${link('sales-meeting',r.id)}">View</a>`:''}<button data-action="edit" data-id="${r.id}">Edit</button>${!s.noAdd?`<button data-action="delete" data-id="${r.id}" aria-label="Delete ${esc(r.name||r.code||'record')}">×</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="${cols.length+1}" class="empty">No records found. Clear filters or add a record.</td></tr>`}</tbody></table></div>`}<div class="pagination"><span>Showing ${list.length?start+1:0} to ${Math.min(start+state.size,list.length)} of ${list.length} entries</span><div class="actions"><span>Show:</span><select id="page-size" aria-label="Rows per page">${[10,25,50,100].map(n=>`<option ${n===state.size?'selected':''}>${n}</option>`).join('')}</select>per page</div><div class="actions"><button data-action="prev" ${state.page===1?'disabled':''}>Previous</button>Page ${state.page} of ${pages}<button data-action="next" ${state.page===pages?'disabled':''}>Next</button></div></div></section>`;
}
function detail(){const r=meeting();if(!r)return'<section class="panel empty">Meeting not found. <a href="#/sales-meeting">Return to meetings</a></section>';let tab=state.tab;
 const content=tab==='Info'?`<div class="detailsgrid">${[['MEETING DETAILS',[['Hospital/Vendor Name',r.name],['Meeting Type',r.type],['Location',r.location],['Employee',r.employee],['GST Number',r.gst],['Address',r.address],['PIN Code',r.pincode]]],['CONTACT INFORMATION',[['Name',r.contact],['Phone',r.phone],['Email',r.email]]],['TIMELINE',[['Created',date(r.created)],['Last Updated',date(r.updated||r.created)],['Remarks',r.remarks]]]].map(([title,fields])=>`<section><h3>${title}</h3><dl>${fields.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'N/A')}</dd></div>`).join('')}</dl></section>`).join('')}</div>`:tab==='Follow-ups'?`<button data-action="activity" data-value="followups">${icon('plus')}Add Follow-up</button>${(r.followups||[]).map((f,i)=>`<div class="listrow"><div><b>${date(f.date)} · ${esc(f.type)}</b><p>${esc(f.outcome||'')}</p><small>${esc(f.remarks)} ${f.nextDate?' · Next: '+date(f.nextDate):''}</small></div><div class="actions">${badge(f.status)}<button data-action="finish-followup" data-index="${i}">Complete</button></div></div>`).join('')||'<p class="empty">No follow-ups yet. Schedule the first follow-up to start tracking.</p>'}`:tab==='Quotations'?`<button data-action="quotation">${icon('plus')}Create Quotation</button>${(r.quotations||[]).map((q,i)=>`<div class="listrow"><div><b>${esc(q.id)}</b><small>Valid until ${date(q.validUntil)} · ${esc(q.remarks)}</small><p>${money(quoteTotal(q))}</p></div><div class="actions"><select data-quote-status="${i}" aria-label="Quotation status">${['Pending','Shared','Accepted','Rejected'].map(s=>`<option ${s===q.status?'selected':''}>${s}</option>`).join('')}</select><button data-action="quote-view" data-index="${i}">View / Print</button><button data-action="quote-export" data-index="${i}">Excel</button></div></div>`).join('')||'<p class="empty">No quotations yet.</p>'}`:tab==='Documents'?`<button data-action="activity" data-value="documents">${icon('plus')}Add Document</button>${(r.documents||[]).map((d,i)=>`<div class="listrow"><div><b>${esc(d.name)}</b><small>${esc(d.fileName||d.url||'')} · ${esc(d.remarks||'')}</small></div><button data-action="document-download" data-index="${i}">Download</button></div>`).join('')||'<p class="empty">No documents uploaded.</p>'}`:`<button data-action="activity" data-value="updates">${icon('plus')}Add New Update</button>${(r.updates||[]).map(u=>`<div class="listrow"><div><b>${esc(u.title)}</b><p>${esc(u.description)}</p><small>${date(u.date)} · ${esc((u.team||[]).join(', '))}</small></div></div>`).join('')||'<p class="empty">No updates yet.</p>'}`;
 return`<div class="crumb"><a href="${link('dashboard')}">Dashboard</a> / <a href="${link('sales-meeting')}">Sales Meetings</a> / #${r.id}</div><div class="pagehead"><div><h1>${esc(r.name||'Unnamed meeting')}</h1><p>${r.type} Meeting #${r.id} ${badge(r.meetingStatus)} ${badge(r.status)}</p></div><div class="actions"><button data-action="complete">${icon('check')}Mark Complete</button><button data-action="edit" data-id="${r.id}">Edit</button></div></div><section class="panel"><div class="actions">${icon('pin')}${esc(r.location||'N/A')} · ${esc(r.employee)} · ${esc(r.contact||'No contact')} · ${esc(r.phone||'')}</div><small>Created ${date(r.created)} · Sample record</small></section><div class="twocol"><section class="panel"><h3>HOPE Lead</h3><p>${r.leadId?'Linked to local HOPE lead #'+r.leadId:'No HOPE lead linked yet.'}</p><button data-action="lead" ${!r.email||r.leadId?'disabled':''}>Generate HOPE Lead</button>${!r.email?'<small>Add contact email to generate a HOPE lead.</small>':''}</section><section class="panel"><h3>Team</h3><p>${esc((r.team||[]).join(', ')||'No team members added yet.')}</p><button data-action="team">Add team members</button></section></div><section class="panel"><div class="tabs" role="tablist">${['Info','Follow-ups','Quotations','Documents','Updates'].map(t=>`<button role="tab" class="${t===tab?'selected':''}" aria-selected="${t===tab}" data-action="detailtab" data-value="${t}">${t}</button>`).join('')}</div><div role="tabpanel" aria-label="${tab}">${content}</div></section>`;
}
function openModal(title,desc,body){let m=$('#modal');m.setAttribute('aria-labelledby','dialog-title');m.innerHTML=`<div class="modalhead"><h2 id="dialog-title">${esc(title)}</h2><button data-action="close" aria-label="Close">×</button></div>${desc?`<p class="modaldesc">${esc(desc)}</p>`:''}${body}`;if(!m.open)m.showModal();}
function closeModal(){$('#modal').close();currentForm=null;quoteDraft=null;}
function fieldHTML(f,value){let id='field-'+f.key,v=value??'';const req=f.required?'required':'',base=`id="${id}" name="${f.key}" ${req}`;let input;
 if(['select','multiselect'].includes(f.type)){let mult=f.type==='multiselect';input=`<select ${base} ${mult?'multiple size="4"':''}>${mult?'':'<option value="">Select '+esc(f.label)+'</option>'}${f.options.map(o=>`<option value="${esc(o)}" ${(mult?(Array.isArray(v)?v:[]).includes(o):v===o)?'selected':''}>${esc(o)}</option>`).join('')}</select>`;}
 else if(f.type==='textarea')input=`<textarea ${base} ${f.key==='summary'?'maxlength="300"':''}>${esc(v)}</textarea>`;
 else if(f.type==='checkbox')return`<label class="inlinecheck"><input type="checkbox" ${base} ${v?'checked':''}>${esc(f.label)}</label>`;
 else if(['image','gallery','file'].includes(f.type))input=`<input ${base} type="file" ${f.type!=='file'?'accept="image/png,image/jpeg,image/webp"':''} ${f.type==='gallery'?'multiple':''}>${v?'<small>Existing file retained unless replaced.</small>':''}<small>Local storage: max 2 MB per file. Gallery: up to 8 images.</small>`;
 else if(['pairs','tiers'].includes(f.type)){let entries=Array.isArray(v)?v:[];input=`<div data-repeat="${f.key}">${entries.map(row=>repeatRow(f.key,row,f.type)).join('')}</div><button type="button" data-action="repeat" data-value="${f.key}" data-kind="${f.type}">${icon('plus')}${f.type==='tiers'?'Add tier':'Add row'}</button>`;}
 else input=`<input ${base} type="${f.type}" value="${f.type==='password'?'':esc(v)}" ${f.type==='number'?'min="0" step="any"':''} ${f.type==='password'?'disabled placeholder="Secure authentication requires a backend"':''} ${f.key==='pincode'?'pattern="[0-9]{6}" title="Enter a six-digit PIN code"':''}>`;
 return`<label class="${['textarea','pairs','tiers','gallery'].includes(f.type)?'wide':''}" for="${id}">${esc(f.label)}${f.required?' *':''}${input}</label>`;
}
function repeatRow(key,row={},type='pairs'){return`<div class="repeatrow"><input data-part="a" placeholder="${type==='tiers'?'Booked boxes from':'Label / Question'}" type="${type==='tiers'?'number':'text'}" ${type==='tiers'?'min="0"':''} value="${esc(row.a??'')}" aria-label="${type==='tiers'?'Booked boxes from':'Label or question'}"><input data-part="b" placeholder="${type==='tiers'?'Price per box':'Value / Answer'}" type="${type==='tiers'?'number':'text'}" ${type==='tiers'?'min="0" step="any"':''} value="${esc(row.b??'')}" aria-label="${type==='tiers'?'Price per box':'Value or answer'}"><button type="button" data-action="remove-row" aria-label="Remove row">×</button></div>`;}
function formGroups(schema){if(schema.meeting)return[['Meeting Details',schema.fields.filter(f=>!['contact','phone','email','generateLead'].includes(f.key))],['Contact Information',schema.fields.filter(f=>['contact','phone','email','generateLead'].includes(f.key))]];if(state.route==='hope-box'){let slices=[['Overview',0,9],['Media',9,12],['Pricing & stock',12,20],['Specifications',20,21],['Price tiers',21,22]];return slices.map(([n,a,b])=>[n,[...schema.fields.slice(a,b),...(n==='Overview'?schema.fields.slice(22):[])]]);}if(state.route==='hope-plan')return[['Details',schema.fields.slice(0,6)],['Tags',schema.fields.slice(6,7)],['Features',schema.fields.slice(7)]];if(state.route==='hope-user')return[['Basic Info',schema.fields.slice(0,7)],['Facility Profile',schema.fields.slice(7)]];if(state.route==='employee')return[['Basic Information',schema.fields.slice(0,7)],['Additional Details',schema.fields.slice(7)]];return[['Details',schema.fields]];}
function editForm(id){let schema=SCHEMAS[state.route]||SCHEMAS['sales-meeting'],k=state.id?'sales-meeting':key(),r=id?(db[k]||[]).find(x=>x.id===id):null;
 if(k==='section')schema={...schema,fields:[F('name','Name','text',[],true),F('routes','Routes','textarea',[],true),F('order','Order','number',[],true),F('status','Status','select',RECORD_STATUS,true)]};
 if(!schema.fields.some(f=>f.key==='status'))schema={...schema,fields:[...schema.fields,F('status','Record status','select',RECORD_STATUS)]};
 let defaults={type:schema.fixedType||'Hospital',meetingStatus:'Pending',status:'Active',employee:'Mohit Singh',discountType:'Percentage',billing:'Monthly',unit:'pcs',qtyPerBox:1,stock:100,moq:5,booked:0,mrp:0,market:0,hopePrice:0,campaignStatus:'Available',role:'Owner / Director',facility:FACILITIES[0],leadStatus:'Pending'},value={...defaults,...r};if(k==='section'&&!r)value.order=Math.max(-1,...db.section.map(row=>Number(row.order)||0))+1;if(schema.fixedType==='Vendor')schema={...schema,fields:schema.fields.map(f=>['name','location'].includes(f.key)?{...f,required:false}:f)};
 schema={...schema,fields:schema.fields.map(f=>{let options=f.options;if(f.key==='location')options=db.location.filter(x=>x.status==='Active').map(x=>x.name);if(['team','employee'].includes(f.key))options=[...new Set([...f.options,...db.employee.map(x=>x.name)])];if(k==='hope-box'&&f.key==='category')options=db['hope-category'].filter(x=>x.status==='Active').map(x=>x.name);if(k==='hope-box'&&f.key==='brand')options=db['hope-brand'].filter(x=>x.status==='Active').map(x=>x.name);return {...f,options};})};
 currentForm={schema,k,id,original:r};let groups=formGroups(schema);
 openModal((id?'Edit ':'New ')+schema.singular,'Changes are saved only in this browser. Authentication and live publishing require backend APIs.',`<form id="record-form" novalidate>${groups.length>1?`<div class="tabs" role="tablist">${groups.map(([name],i)=>`<button type="button" role="tab" aria-selected="${!i}" class="${!i?'selected':''}" data-action="formtab" data-index="${i}">${name}</button>`).join('')}</div>`:''}${groups.map(([name,fields],i)=>`<section class="formsection formgrid" data-formtab="${i}" aria-label="${name}" ${i?'hidden':''}>${fields.map(f=>fieldHTML(f,value[f.key])).join('')}</section>`).join('')}<p class="error" id="form-error" role="alert"></p><div class="formfoot"><button type="button" data-action="close">Cancel</button><button type="submit" class="primary">${id?'Save Changes':'Add '+schema.singular}</button></div></form>`);
}
function formTab(index){$$('[data-formtab]').forEach(s=>s.hidden=s.dataset.formtab!==String(index));$$('[data-action="formtab"]').forEach(b=>{b.classList.toggle('selected',b.dataset.index===String(index));b.setAttribute('aria-selected',String(b.dataset.index===String(index)));});}
async function readFile(file){if(file.size>2*1024*1024)throw Error('File must be 2 MB or smaller for browser storage.');return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read file.'));reader.readAsDataURL(file);});}
async function collectFields(fields,form,original={}){let data={};for(const f of fields){let input=form.elements.namedItem(f.key);if(['pairs','tiers'].includes(f.type)){data[f.key]=[...form.querySelectorAll(`[data-repeat="${f.key}"] .repeatrow`)].map(row=>({a:row.querySelector('[data-part="a"]').value,b:row.querySelector('[data-part="b"]').value}));continue;}if(!input||f.type==='password')continue;if(f.type==='checkbox')data[f.key]=input.checked;else if(f.type==='multiselect')data[f.key]=[...input.selectedOptions].map(o=>o.value);else if(['image','gallery','file'].includes(f.type)){if(input.files.length){if(f.type==='gallery'&&input.files.length>8)throw Error('Choose up to 8 gallery images.');for(const file of input.files)if(f.type!=='file'&&!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Select a PNG, JPEG or WEBP image.');data[f.key]=f.type==='gallery'?await Promise.all([...input.files].map(readFile)):await readFile(input.files[0]);if(f.type==='file')data.fileName=input.files[0].name;}else data[f.key]=original[f.key]||'';}else data[f.key]=f.type==='number'?Number(input.value):input.value.trim();}return data;}
async function submitRecord(form){const invalid=[...form.querySelectorAll('input,select,textarea')].find(x=>!x.checkValidity());if(invalid){let section=invalid.closest('[data-formtab]');if(section)formTab(section.dataset.formtab);invalid.reportValidity();return;}let {schema,k,id,original}=currentForm;
 try{let data=await collectFields(schema.fields,form,original);if(k==='section'){saveSectionRecord(data,id);closeModal();sidebar();renderMain();toast('Section saved.');return;}if(data.generateLead&&!data.email)throw Error('Contact email is required to generate a HOPE lead.');if(k==='hope-coupon'&&data.discountType==='Percentage'&&data.discount>100)throw Error('Percentage discount cannot exceed 100.');if(k==='hope-plan'&&data.discounted>data.price)throw Error('Discounted price cannot exceed original price.');if(k==='hope-box'&&data.booked>data.stock)throw Error('Booked boxes cannot exceed total boxes.');if(k==='hope-box'&&data.opens&&data.closes&&data.closes<data.opens)throw Error('Closing time must be after opening time.');
 if(!id){data={id:Math.max(0,...db[k].map(r=>r.id))+1,status:'Active',order:db[k].length+1,created:today(),employee:'Mohit Singh',...data};if(schema.meeting)data={followups:[],quotations:[],documents:[],updates:[],...data};db[k].unshift(data);}else{let index=db[k].findIndex(r=>r.id===id);db[k][index]={...original,...data,updated:today()};data=db[k][index];}
 if(data.generateLead&&!data.leadId)generateLead(data);state.snapshot=false;save();closeModal();sidebar();renderMain();toast('Saved to local workspace.');}catch(error){$('#form-error').textContent=error.message;}}
function generateLead(r){if(!r.email)return;let id=Math.max(0,...db['hope-lead'].map(x=>x.id))+1;db['hope-lead'].unshift({id,name:r.contact||r.name,email:r.email,phone:r.phone||'',facility:FACILITIES[0],leadStatus:'Pending',employee:r.employee,status:'Active',created:today(),sourceMeeting:r.id});r.leadId=id;}
function activityForm(type){activityType=type;let fields=type==='followups'?[F('date','Date','date',[],true),F('status','Status','select',['Scheduled','Completed','Cancelled']),F('type','Type','select',['Phone Call','Site Visit','Email','WhatsApp','Other']),F('nextDate','Next Follow-up Date','date'),F('outcome','Outcome'),F('remarks','Remarks','textarea'),F('team','Tag Team Members','multiselect',EMPLOYEES)]:type==='documents'?[F('name','Name','text',[],true),F('file','Document','file',[],true),F('remarks','Remarks','textarea'),F('team','Tag Team Members','multiselect',EMPLOYEES)]:[F('title','Title','text',[],true),F('date','Date','date',[],true),F('description','Update','textarea',[],true),F('team','Tag Team Members','multiselect',EMPLOYEES)];
 currentForm={fields};openModal(type==='followups'?'New Follow-up':type==='documents'?'New Document':'New Update','Local preview only. Team tagging does not send notifications.',`<form id="activity-form"><div class="formgrid">${fields.map(f=>fieldHTML(f,f.key==='date'?today():f.key==='status'?'Scheduled':'')).join('')}</div><p id="form-error" class="error" role="alert"></p><div class="formfoot"><button type="button" data-action="close">Cancel</button><button type="submit" class="primary">Save</button></div></form>`);}
function quotationForm(){quoteDraft=[{product:'',specs:'',hsn:'',gst:12,qty:1,price:0}];openModal('Create Quotation','Add line items now and fill product details later if needed. Confirm product specifications, HSN and GST before use.',`<form id="quotation-form"><div class="formgrid"><label>Valid Until<input name="validUntil" type="date" required></label><label>Remarks<input name="remarks"></label></div><div class="toolbar" style="margin-top:24px"><h3>Line Items *</h3><button type="button" data-action="quote-add">Add Item</button></div><div class="tablewrap quoteitems"><table><thead><tr><th>Product</th><th>Specifications</th><th>HSN</th><th>GST %</th><th>Qty</th><th>Unit Price</th><th>Total</th><th></th></tr></thead><tbody id="quote-body"></tbody></table></div><div class="quotetotal" id="quote-total"></div><div class="formfoot"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Create Quotation</button></div></form>`);renderQuoteItems();}
function renderQuoteItems(){$('#quote-body').innerHTML=quoteDraft.map((i,n)=>`<tr data-quote-row="${n}"><td><input aria-label="Product ${n+1}" data-qi="product" value="${esc(i.product)}" required></td><td><input aria-label="Specifications ${n+1}" data-qi="specs" value="${esc(i.specs)}"></td><td><input aria-label="HSN ${n+1}" data-qi="hsn" value="${esc(i.hsn)}"></td><td><select data-qi="gst" aria-label="GST percent ${n+1}">${[0,5,12,18,28].map(v=>`<option ${Number(i.gst)===v?'selected':''} value="${v}">${v}%</option>`).join('')}</select></td><td><input aria-label="Quantity ${n+1}" data-qi="qty" type="number" min="0.001" step="any" value="${i.qty}" required></td><td><input aria-label="Unit price ${n+1}" data-qi="price" type="number" min="0" step="0.01" value="${i.price}" required></td><td data-line-total>${money(i.qty*i.price*(1+i.gst/100))}</td><td><button type="button" data-action="quote-remove" data-index="${n}" aria-label="Remove item ${n+1}" ${quoteDraft.length===1?'disabled':''}>×</button></td></tr>`).join('');$('#quote-total').textContent='Total: '+money(quoteTotal({items:quoteDraft}));}
function quotePreview(q,r){openModal('Quotation '+q.id,'Local quotation preview. Verify all commercial and tax details before sharing.',`<div class="pagehead"><div><h2>HOSPkart Healthique Pvt. Ltd.</h2><p>+91 9216015265</p></div>${badge(q.status)}</div><p><b>To:</b> ${esc(r.name)}</p><p><b>Valid Until:</b> ${date(q.validUntil)}</p>${q.lineItemsText?`<p><b>Imported line items:</b> ${esc(q.lineItemsText)}</p><p class="muted">Item tax details were not included in the original report.</p>`:''}<div class="tablewrap"><table><thead><tr><th>Product</th><th>Specifications</th><th>HSN</th><th>GST</th><th>Qty</th><th>Unit Price</th><th>Total</th></tr></thead><tbody>${(q.items||[]).map(i=>`<tr><td>${esc(i.product)}</td><td>${esc(i.specs)}</td><td>${esc(i.hsn)}</td><td>${i.gst}%</td><td>${i.qty}</td><td>${money(i.price)}</td><td>${money(i.qty*i.price*(1+i.gst/100))}</td></tr>`).join('')}</tbody></table></div><p class="quotetotal">Total: ${money(quoteTotal(q))}</p><p>${esc(q.remarks)}</p><div class="formfoot"><button data-action="close">Close</button><button data-action="print">Print</button></div>`);}
function help(){return`<div class="pagehead"><div><h1>Setup & API requirements</h1><p>Frontend recreation based on the signed-in HOSPkart CRM.</p></div><span class="badge">Local mode</span></div><section class="panel help"><h3>Run locally in VS Code</h3><ol><li>Extract the ZIP and open the <b>hospkart-crm</b> folder in VS Code.</li><li>Open <b>index.html</b> with Live Server, or double-click <b>HOSPkart_CRM_Standalone.html</b>.</li><li>Data saves in this browser. Use Download local backup before clearing browser data.</li></ol><h3>Working frontend features</h3><p>Sidebar navigation; responsive layouts; dark theme; search; filters; table/card views; sorting; column visibility; pagination; add/edit/delete local records; meeting details; teams; follow-ups; GST quotation calculations and printing; local documents; product media, specifications and price tiers; local JSON backup and restore; genuine XLSX exports.</p><div class="tablewrap"><table><thead><tr><th>Feature</th><th>Local frontend</th><th>Backend required</th></tr></thead><tbody>${[['Authentication / roles / MFA','UI demonstration only; no passwords saved','Secure sessions, authorization and password/MFA management'],['CRM records','Browser localStorage','Database CRUD, server validation, audit log, shared synchronization'],['Dashboard','Observed aggregate snapshot or calculated local totals','Live aggregate and reporting queries'],['Documents / images','Up to 2 MB per local file','Private object storage, scanning and authenticated downloads'],['Team tags / reminders','Saves tags and dates','Email, WhatsApp and scheduled notifications'],['Quotations','Calculation, status, Excel and print','Official numbering, approvals, PDF storage and delivery'],['Products / blogs / plans','Local drafts and editors','Publishing, file CDN, pricing and stock enforcement'],['Orders / subscriptions / payments','Sample records and local edits','Payment gateway, webhooks, fulfillment and accounting'],['Languages','English interface; selector explains API requirement','Verified translations and locale dictionaries']].map(([a,b,c])=>`<tr><td>${a}</td><td>${b}</td><td>${c}</td></tr>`).join('')}</tbody></table></div></section><section class="panel help"><h3>Scope and evidence</h3><p>Dashboard and all 18 sidebar destinations were opened in the authenticated session on 31 October 2026. Meeting details and creation, follow-ups, quotation editor, documents and updates were inspected. Product, lead, user, employee, category, brand, blog, coupon, plan, role and location forms were reviewed. Some screens briefly displayed loading placeholders. Secondary edit dialogs, every record detail, every pagination page, security workflows and payment actions were not exhaustively inspected.</p><p>Layout follows the observed white HOPE admin design, blue/violet actions, soft navigation, rounded controls and bordered dashboard cards. The displayed HOPE logo was retained. Font uses a local system fallback. Demo content and secondary administration layouts are approximations; this is a reconstructed frontend, not the original source code or a database backup.</p><p><b>Reference totals:</b> 425 meetings, 612 follow-ups, 228 scheduled, 14 quotations, ₹2,28,947 quotation value, 5 accepted. These are explicitly labelled historical observations and do not represent the local sample dataset. Filters and edits switch to local totals.</p></section>`;}
function settings(){return`<div class="crumb"><a href="${link('dashboard')}">Dashboard</a> / Settings</div><section class="panel settings"><h3>Payment settings</h3><p class="muted">Set the subscription price charged to customers.</p><p class="notice">Local preview setting only. No customer is charged.</p><form id="settings-form"><label>Subscription price *<input type="number" name="subscriptionPrice" min="0" step="0.01" required value="${Number(db.settings?.subscriptionPrice)||0}"></label><div class="formfoot"><button class="primary" type="submit">Save changes</button></div></form></section>`;}
function renderMain(){if(state.route==='operations'){renderOperations();return;}document.title=(state.id?'Sales Meeting #'+state.id:state.route==='dashboard'?'Sales Meeting Dashboard':SCHEMAS[state.route]?.title||'HOSPkart CRM')+' | Hope Admin';$('#main').innerHTML=state.id?detail():state.route==='dashboard'?dashboard():state.route==='settings'?settings():state.route==='help'?help():state.route==='operations'?operationsPage():SCHEMAS[state.route]?tablePage():'<section class="panel empty">Page not found. <a href="#/sales-meeting/dashboard">Open dashboard</a></section>';}
function parseRoute(){let raw=location.hash.slice(1)||'/sales-meeting/dashboard',parts=raw.split('?'),path=parts[0].split('/').filter(Boolean),route=path.join('/')==='sales-meeting/dashboard'?'dashboard':path[0]||'dashboard';state.route=route;if(route==='section'){state.sort='order';state.desc=false;}state.id=route==='sales-meeting'&&/^\d+$/.test(path[1]||'')?Number(path[1]):null;state.search='';state.page=1;state.filters=Object.fromEntries(new URLSearchParams(parts[1]||''));if(state.filters.status==='All')delete state.filters.status;if(state.filters.status==='Pending Payment')state.filters.status='PendingPayment';if(route!=='operations'&&Object.keys(state.filters).length)state.snapshot=false;state.view='table';state.tab='Follow-ups';state.subtab='Subscriptions';document.body.classList.remove('mobile-open');sidebar();topbar();renderMain();}
function download(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportTable(){if(state.route==='dashboard'||SCHEMAS[state.route]?.meeting){exportOriginalSalesReport();return;}
 let s=SCHEMAS[state.route]||SCHEMAS['sales-meeting'],list=filtered();download(excelWorkbook(s.cols.map(([,label])=>label),list.map(r=>s.cols.map(([k])=>Array.isArray(r[k])?r[k].length:r[k]??''))),`HOSPkart_${state.route}_Local.xlsx`);toast('Exported all matching local records to Excel.');}

const ACTIONS={
 'section-menu':openSectionMenu,
 'section-copy':copySectionRoutes,
 'section-reset':()=>{state.search='';state.filters={};state.hidden.section=[];state.sort='order';state.desc=false;state.page=1;renderMain();},
 sidebar:()=>{if(matchMedia('(max-width:760px)').matches)document.body.classList.toggle('mobile-open');else document.body.classList.toggle('collapsed');},
 theme:()=>{document.body.classList.toggle('dark');try{localStorage.setItem(KEY+'-theme',document.body.classList.contains('dark')?'dark':'light');}catch{}},
 language:()=>openModal('Language','The inspected CRM provides a language selector. This standalone build includes English UI only.','<p>Additional languages require reviewed translation dictionaries. No live translation service is connected.</p><div class="formfoot"><button data-action="close">Close</button></div>'),
 profile:()=>openModal('Local Admin','Frontend preview · no authenticated backend session',`<p>Changes are stored in this browser. Login, account access, permissions and MFA must be implemented by your backend team.</p><div class="formfoot"><a class="btn" href="#/help" data-action="close">Integration guide</a><button data-action="login-preview">Preview login</button><button data-action="close">Close</button></div>`),
 'login-preview':()=>openModal('Welcome back','Enter your credentials to access your account',`<p class="notice">Login UI preview. Real authentication requires your backend. Do not enter production credentials here.</p><div class="formgrid"><label class="wide">Email<input type="email" placeholder="name@example.com" disabled></label><label class="wide">Password<input type="password" placeholder="Enter your password" disabled></label></div><div class="formfoot"><button class="primary" data-action="close">Continue local demo</button></div>`),
 close:closeModal,
 search:()=>{openModal('Search','Find pages and local meetings.',`<input id="global-search" type="search" aria-label="Search pages and meetings" placeholder="Type a page or meeting name"><div id="search-results" class="dropdownlist"></div>`);searchResults('');},
 clear:()=>{state.filters={};state.search='';state.page=1;state.snapshot=false;renderMain();},
 snapshot:()=>{state.snapshot=!state.snapshot;state.filters={};state.search='';renderMain();},
 export:exportTable,
 add:()=>editForm(null),edit:b=>editForm(Number(b.dataset.id)),
 delete:b=>{let id=Number(b.dataset.id),k=key();openModal('Delete local record?','This affects the local sample workspace only.',`<div class="formfoot"><button data-action="close">Cancel</button><button data-action="confirm-delete" data-id="${id}" data-key="${k}">Delete local record</button></div>`);},
 'confirm-delete':b=>{if(b.dataset.key==='section'){if(!commitSections(db.section.filter(r=>r.id!==Number(b.dataset.id))))return;closeModal();sidebar();renderMain();toast('Section deleted.');return;}db[b.dataset.key]=db[b.dataset.key].filter(r=>r.id!==Number(b.dataset.id));save();closeModal();sidebar();renderMain();toast('Local record deleted.');},
 columns:()=>{const cols=SCHEMAS[state.route].cols;openModal('Visible Columns','Choose which columns to display in this table.',`<div class="formgrid">${cols.map(([k,label])=>`<label class="inlinecheck"><input type="checkbox" data-column="${k}" ${!(state.hidden[state.route]||[]).includes(k)?'checked':''}>${label}</label>`).join('')}</div><div class="formfoot"><button data-action="close">Done</button></div>`);},
 sort:b=>{let k=b.dataset.value;state.desc=state.sort===k?!state.desc:false;state.sort=k;renderMain();},view:b=>{state.view=b.dataset.value;renderMain();},prev:()=>{state.page--;renderMain();},next:()=>{state.page++;renderMain();},
 detailtab:b=>{state.tab=b.dataset.value;renderMain();},subtab:b=>{state.subtab=b.dataset.value;state.page=1;renderMain();},formtab:b=>formTab(b.dataset.index),
 repeat:b=>{let container=$(`[data-repeat="${b.dataset.value}"]`);container.insertAdjacentHTML('beforeend',repeatRow(b.dataset.value,{},b.dataset.kind));},'remove-row':b=>b.closest('.repeatrow').remove(),
 complete:()=>{meeting().meetingStatus='Completed';meeting().updated=today();state.snapshot=false;save();renderMain();toast('Meeting marked complete locally.');},
 lead:()=>{generateLead(meeting());save();renderMain();toast('HOPE lead created locally.');},
 team:()=>openModal('Team members','Assignments are local; no notification is sent.',`<form id="team-form">${fieldHTML(F('team','Team members','multiselect',EMPLOYEES),meeting().team||[])}<div class="formfoot"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save Team</button></div></form>`),
 activity:b=>activityForm(b.dataset.value),
 'finish-followup':b=>{meeting().followups[Number(b.dataset.index)].status='Completed';save();renderMain();},
 quotation:quotationForm,
 'quote-add':()=>{quoteDraft.push({product:'',specs:'',hsn:'',gst:12,qty:1,price:0});renderQuoteItems();},
 'quote-remove':b=>{quoteDraft.splice(Number(b.dataset.index),1);renderQuoteItems();},
 'quote-view':b=>quotePreview(meeting().quotations[Number(b.dataset.index)],meeting()),
 'quote-export':b=>{let q=meeting().quotations[Number(b.dataset.index)];download(excelWorkbook(['Product','Specifications','HSN','GST %','Qty','Unit Price','Total'],[...q.items.map(i=>[i.product,i.specs,i.hsn,+i.gst,+i.qty,+i.price,i.qty*i.price*(1+i.gst/100)]),['TOTAL','','','','','',quoteTotal(q)]]),q.id+'.xlsx');},
 print:()=>window.print(),
 'document-download':b=>{let d=meeting().documents[Number(b.dataset.index)];const target=d.file||d.url;if(!target||!/^data:|^https:\/\//i.test(target)){toast('No local file or original HTTPS document link is available.');return;}let a=document.createElement('a');a.href=target;if(/^https:/i.test(target)){a.target='_blank';a.rel='noopener noreferrer';}a.download=d.fileName||d.name;document.body.appendChild(a);a.click();a.remove();},
 summaryfilter:b=>{let v=b.dataset.value;state.filters={};if(['Paid','Unpaid'].includes(v))state.filters.payment=v;else if(v==='Delivered')state.filters.deliveryStatus=v;else if(v)state.filters.status=v;state.page=1;renderMain();},
 refresh:()=>{renderMain();toast('Local records refreshed. Live API is not connected.');},
 backup:()=>download(new Blob([JSON.stringify({format:'hospkart-crm-local-v1',exportedAt:new Date().toISOString(),data:db},null,2)],{type:'application/json'}),'HOSPkart_Local_Backup.json'),
 restore:()=>openModal('Restore local backup','This replaces your current local workspace. Download a backup first if needed.',`<form id="restore-form"><label>Backup JSON file<input name="backup" type="file" accept=".json,application/json" required></label><p class="error" id="form-error"></p><div class="formfoot"><button type="button" data-action="close">Cancel</button><button type="submit">Restore local data</button></div></form>`)
};
function searchResults(query){let q=query.toLowerCase();let pages=[['dashboard','Sales Meeting Dashboard'],['sales-meeting','All Meetings'],...Object.entries(SCHEMAS).map(([k,s])=>[k,s.title]),...OPS_MODULES.map(([id,label])=>['operations?module='+id,label]),['settings','Settings'],['help','Setup & API requirements']].filter(([,t])=>t.toLowerCase().includes(q));let matches=db['sales-meeting'].filter(r=>(r.name||'').toLowerCase().includes(q)).slice(0,8);$('#search-results').innerHTML=[...pages.map(([r,t])=>`<a class="navrow" href="${link(r)}" data-action="close">${icon('file')}${t}</a>`),...matches.map(r=>`<a class="navrow" href="${link('sales-meeting',r.id)}" data-action="close">${icon('hand')}${esc(r.name)} #${r.id}</a>`)].join('')||'<p class="empty">No matching pages or meetings.</p>';}
document.addEventListener('click',event=>{let b=event.target.closest('[data-action]');if(!b||b.disabled)return;let action=ACTIONS[b.dataset.action];if(action){if(b.tagName!=='A')event.preventDefault();action(b);}});
document.addEventListener('change',event=>{let el=event.target;if(el.matches('[data-section-field]')){updateSectionField(el);return;}if(el.matches('[data-filter]')){state.filters[el.dataset.filter]=el.value;state.page=1;state.snapshot=false;if(state.filters.from&&state.filters.to&&state.filters.from>state.filters.to){state.filters.to=state.filters.from;toast('End date adjusted to the start date.');}renderMain();}if(el.id==='page-size'){state.size=Number(el.value);state.page=1;renderMain();}if(el.dataset.column){let k=el.dataset.column;state.hidden[state.route]??=[];state.hidden[state.route]=state.hidden[state.route].filter(x=>x!==k);if(!el.checked)state.hidden[state.route].push(k);renderMain();}if(el.matches('[data-quote-status]')){meeting().quotations[Number(el.dataset.quoteStatus)].status=el.value;save();toast('Quotation status saved locally.');}});
document.addEventListener('input',event=>{let el=event.target;if(el.id==='global-search')searchResults(el.value);if(el.id==='table-search'){state.search=el.value;state.page=1;let pos=el.selectionStart;renderMain();let input=$('#table-search');input.focus();input.setSelectionRange(pos,pos);}if(el.matches('[data-qi]')){let n=Number(el.closest('[data-quote-row]').dataset.quoteRow),key=el.dataset.qi;quoteDraft[n][key]=['gst','qty','price'].includes(key)?Number(el.value):el.value;el.closest('tr').querySelector('[data-line-total]').textContent=money(quoteTotal({items:[quoteDraft[n]]}));$('#quote-total').textContent='Total: '+money(quoteTotal({items:quoteDraft}));}});
document.addEventListener('submit',async event=>{event.preventDefault();let form=event.target;if(form.id==='record-form'){await submitRecord(form);return;}if(form.id==='activity-form'){try{let r=meeting(),data=await collectFields(currentForm.fields,form);if(activityType==='followups'&&data.nextDate&&data.nextDate<data.date)throw Error('Next follow-up date must not be before the follow-up date.');r[activityType]??=[];r[activityType].push(data);if(activityType==='followups'&&data.nextDate)r.followups.push({date:data.nextDate,status:'Scheduled',type:data.type,remarks:'Next follow-up',team:data.team||[]});save();closeModal();renderMain();toast('Saved locally.');}catch(e){$('#form-error').textContent=e.message;}return;}if(form.id==='quotation-form'){let f=new FormData(form),r=meeting();r.quotations??=[];r.quotations.push({id:'LOCAL-QTN-'+r.id+'-'+Date.now(),validUntil:f.get('validUntil'),remarks:f.get('remarks'),status:'Pending',items:structuredClone(quoteDraft)});save();closeModal();renderMain();toast('Quotation created locally.');return;}if(form.id==='team-form'){meeting().team=[...form.elements.team.selectedOptions].map(o=>o.value);save();closeModal();renderMain();return;}if(form.id==='settings-form'){db.settings={subscriptionPrice:Number(new FormData(form).get('subscriptionPrice'))};save();toast('Subscription price saved locally. No payment was processed.');return;}if(form.id==='restore-form'){try{let file=form.elements.backup.files[0];if(file.size>20*1024*1024)throw Error('Backup is too large (max 20 MB).');let backup=JSON.parse(await file.text());if(backup.format!=='hospkart-crm-local-v1'||!backup.data)throw Error('Invalid HOSPkart backup format.');for(let k of Object.keys(SCHEMAS).filter(k=>!SCHEMAS[k].meeting||k==='sales-meeting'))if(!Array.isArray(backup.data[k])||backup.data[k].some(r=>!r||typeof r!=='object'||!Number.isFinite(r.id)))throw Error('Backup has missing or invalid records: '+k);db=backup.data;save();closeModal();parseRoute();toast('Local backup restored.');}catch(e){$('#form-error').textContent=e.message;}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();ACTIONS.search();}});
window.addEventListener('hashchange',()=>{if($('#modal').open)closeModal();parseRoute();window.scrollTo({top:0});});
try{if(localStorage.getItem(KEY+'-theme')==='dark')document.body.classList.add('dark');}catch{}
parseRoute();if(!storageOK)toast('Browser storage is unavailable. Use backups to retain your changes.');

loadOriginalSalesReport();

// Global QuoteSaarthi launcher is outside #main, so chat survives navigation.
function initializeQuoteRobot(){
 const launcher=document.createElement('button');launcher.type='button';launcher.className='quote-robot-launcher';launcher.id='quote-robot-launcher';launcher.setAttribute('aria-label','Open AI Assistance robot assistant');launcher.setAttribute('aria-controls','quote-robot-panel');launcher.setAttribute('aria-expanded','false');
 launcher.innerHTML='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 8V4m-2 0h4M6 16H3v7h3m20-7h3v7h-3"/><rect x="6" y="9" width="20" height="19" rx="6"/><circle cx="12" cy="17" r="1.5"/><circle cx="20" cy="17" r="1.5"/><path d="M12 23h8"/></svg><span class="quote-robot-label">Ask AI Assistance</span>';
 const panel=document.createElement('section');panel.id='quote-robot-panel';panel.className='quote-robot-panel';panel.hidden=true;panel.setAttribute('aria-label','AI Assistance robot assistant');
 const loading=document.createElement('div');loading.className='quote-robot-loading';loading.setAttribute('role','status');loading.textContent='Opening AI Assistance…';panel.appendChild(loading);
 let frame=null,timeout=null;
 const theme=()=>{if(frame?.contentWindow)frame.contentWindow.postMessage({type:'crm-theme',dark:document.body.classList.contains('dark')},location.origin);};
 function syncWorkspaceContext(){
  if(!frame?.contentWindow||loading.hidden===false)return;
  const current_view=state.route==='operations'?(state.filters.module||'dashboard'):'dashboard';
  frame.contentWindow.postMessage({type:'crm-assistant-context',context:{current_view,selected_client:null}},location.origin);
  const operations=$('#operations-frame');
  if(state.route==='operations'&&operations?.contentWindow)operations.contentWindow.postMessage({type:'crm-assistant-context-request'},location.origin);
 }
 window.addEventListener('hashchange',syncWorkspaceContext);
 window.addEventListener('message',event=>{
  const operations=$('#operations-frame');
  if(event.origin!==location.origin||!operations||event.source!==operations.contentWindow||!frame?.contentWindow)return;
  if(event.data?.type==='crm-assistant-context-response'&&state.route==='operations')frame.contentWindow.postMessage({type:'crm-assistant-context',context:event.data.context},location.origin);
  if(event.data?.type==='crm-counts-changed'){frame.contentWindow.postMessage({type:'crm-workspace-updated'},location.origin);syncWorkspaceContext();}
 });
 function close(){panel.hidden=true;launcher.setAttribute('aria-expanded','false');launcher.focus();}
 function open(){
  panel.hidden=false;launcher.setAttribute('aria-expanded','true');
  if(location.protocol==='file:'){loading.textContent='Open http://localhost:5500 to use AI Assistance.';return;}
  if(!frame){
   frame=document.createElement('iframe');frame.title='AI Assistance';frame.src='/operations/?view=assistant&embedded=1&widget=1&theme='+(document.body.classList.contains('dark')?'dark':'light');panel.appendChild(frame);
   frame.addEventListener('load',theme);
   timeout=setTimeout(()=>{if(!loading.hidden){loading.textContent='AI Assistance could not finish loading. Check localhost and retry.';const retry=document.createElement('button');retry.textContent='Retry';retry.onclick=()=>{frame.remove();frame=null;loading.textContent='Opening AI Assistance…';open();};loading.appendChild(retry);}},25000);
  }else if(loading.hidden){frame.contentWindow.postMessage({type:'crm-module',view:'assistant'},location.origin);frame.focus();}
  theme();syncWorkspaceContext();
 }
 launcher.addEventListener('click',()=>panel.hidden?open():close());
 window.addEventListener('message',event=>{
  if(event.origin!==location.origin||!frame||event.source!==frame.contentWindow)return;
  if(event.data?.type==='crm-ready'){clearTimeout(timeout);loading.hidden=true;theme();syncWorkspaceContext();if(!panel.hidden)frame.focus();}
  if(event.data?.type==='crm-assistant-close')close();
 });
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!panel.hidden)close();});
 new MutationObserver(theme).observe(document.body,{attributes:true,attributeFilter:['class']});
 document.body.append(panel,launcher);
}
initializeQuoteRobot();
